SELECT jsonb_build_object('customers',(SELECT count(*) FROM app.customer_profiles WHERE id IN ('479623d1-4924-5118-889e-03291bfefb35')),'commands',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id IN ('76fd3fc8-9ebc-5b9d-bde4-46fc4e6c76e1','904717b2-ce26-5402-8265-bc8eaccc01cb')),'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE customer_profile_id IN ('479623d1-4924-5118-889e-03291bfefb35')),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE aggregate_kind='CustomerProfile' AND aggregate_id IN ('479623d1-4924-5118-889e-03291bfefb35')),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE aggregate_kind='CustomerProfile' AND aggregate_id IN ('479623d1-4924-5118-889e-03291bfefb35')),'effects',(SELECT count(*) FROM platform.runtime_effect_receipt WHERE command_receipt_id IN ('76fd3fc8-9ebc-5b9d-bde4-46fc4e6c76e1','904717b2-ce26-5402-8265-bc8eaccc01cb')),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id IN ('479623d1-4924-5118-889e-03291bfefb35')));
